import { d } from './full-schema.mjs';
export const contemporaryDossiers = {
  'poverty-alleviation': [
    d('长期减贫与集中攻坚的区别', 'Long-run reduction and the targeted campaign',
      '改革以来农业生产率、工业就业、城市化和基础设施共同推动大规模减贫，2010年代精准扶贫是长期进程中的一个阶段。世界银行与国务院发展研究中心报告所述约八亿人摆脱国际极端贫困，采用报告当时的贫困线和数据，不能全部归于最后几年或某位领导人。\n\n贫困减少来自家庭劳动、教育、迁移、市场机会和公共投入，多种机制相互配合。政治动员对资源集中有作用，也要审视谁被识别、服务是否持续及地方如何执行。宏观成就可以明确承认，具体项目仍需逐项评估，二者不构成相互排斥的叙述。',
      'Agricultural productivity, jobs, urbanization and infrastructure drove long-run reduction. Targeted poverty alleviation was a later phase. The roughly 800 million figure uses the 2022 report’s historical international line and cannot all be assigned to one campaign.\n\nHousehold work, markets and public investment interacted. Aggregate achievement and project-level scrutiny are compatible.', ['poverty-report']),
    d('建档立卡与识别误差', 'Registration and identification errors',
      '精准识别试图把支持落实到具体家庭，收入、住房、教育和健康情况进入登记。家庭收入不稳定、外出劳动难统计和地方关系可能产生漏识别或错误纳入。被登记不是贫困全部现实的完美镜像，未被登记也不证明生活没有困难。\n\n干部考核推动核查与资源下沉，也可能诱发材料负担、过度证明和数字压力。应评价独立抽查、申诉、动态调整和退出后跟踪，而不只看完成率。贫困家庭的声音和选择需要进入研究，不能把他们仅作为项目验收表中的对象。',
      'Household registers sought precise targeting but volatile income, migration and local relationships could generate exclusion or inclusion errors. Registration was not a perfect map of need.\n\nPerformance pressure encouraged effort and paperwork risks. Appeals, independent checks and follow-up matter alongside completion rates and beneficiaries’ own choices.', ['poverty-report']),
    d('产业、就业与易地搬迁', 'Industry support, employment and relocation',
      '产业扶持、就业培训和搬迁试图改变长期机会，项目是否成功取决于市场、交通、技能和经营管理。补贴建立的企业不一定持续盈利，培训人数也不等于稳定就业。家庭收入应观察净收益与风险，不能把项目营业额直接当成每户收入。\n\n搬迁可能改善住房、学校与医疗可达性，同时使居民离开土地、亲属和熟悉的生计。自愿程度、后续工作、养老和社区关系决定长期福利。新房建成是可见成果，却不能单独证明生活已经改善全部维度，尤其需要跟踪老人、残障者和照护家庭。',
      'Industry, training and relocation depended on markets, access and management. Business revenue and training attendance did not establish household net income or durable jobs.\n\nNew housing could improve services while disrupting land-based livelihoods and networks. Consent, employment and care determine long-term welfare beyond construction.', ['poverty-report']),
    d('健康、教育与避免返贫', 'Health, education and preventing renewed poverty',
      '疾病、失业和照护负担可能使刚越过收入线的家庭再次困难，减贫因此需要医保、教育与社会救助衔接。参保不等于全部治疗可负担，义务教育入学也不等于学习质量相同。家庭支付、交通与陪护时间都影响服务实际取得。\n\n儿童教育改善具有长期作用，不能在项目结束当年就完整测量。残障和慢性病家庭需要持续支持，不能要求每个家庭通过创业自我解决。防返贫监测应注意隐私和申诉，避免为证明达标而压制困难反馈。',
      'Illness, unemployment and care can push households back into hardship. Insurance enrollment and school access do not guarantee affordability or quality.\n\nEducation yields long-term effects; disabled and chronically ill households need sustained support. Monitoring should protect privacy and allow reporting difficulty rather than only demonstrating success.', ['poverty-report', 'universal-health-2013', 'health-reform-2016']),
    d('贫困线与2020年宣告的含义', 'Poverty lines and the 2020 achievement claim',
      '中国宣布完成现行标准下农村绝对贫困消除目标，需保留农村、现行标准与政策验收的范围。它不等于所有居民达到高收入，也不等于城市贫困、相对贫困和生活脆弱性已经消失。国际贫困线采用购买力平价，更新后不能把不同版本数字直接比较。\n\n收入线有助一致统计，却不能完全表示住房、健康、尊严和安全。研究应说明数据年、价格基准与覆盖人口，也应使用多维指标。肯定绝对贫困大幅下降，与指出新标准和更广福利需求，可以在同一严谨口径下成立。',
      'The announced elimination concerned rural absolute poverty under the applicable national standard. It did not end urban need, relative poverty or vulnerability. International PPP lines also change.\n\nIncome thresholds aid measurement without fully describing health, housing or security. Dates, coverage and multidimensional indicators allow achievement and remaining needs to be assessed together.', ['poverty-report', 'nbs-2025']),
    d('乡村振兴与下一阶段', 'Rural revitalization and the next stage',
      '攻坚后转向乡村振兴和持续支持，农业、公共服务与城乡流动成为长期议题。年轻劳动力外出可以增加收入，也使地方照护、教育和产业面临结构变化。不能把所有留村者视作落后，也不能以城市化为名忽略居民保留土地与文化联系的选择。\n\n2026年经济再平衡讨论更强调消费与社会保护，减贫经验需要放到新的增长条件中。以往有效的投资方式未必在每个地方继续有效，资源约束要求评估持续性。本书将已实现变化与未来目标分别记录，不把政策规划写成已经完成的社会结果。',
      'Rural revitalization connects agriculture, services and mobility. Migration improves income while changing local care and education; residents’ land and cultural choices matter.\n\nRebalancing in 2026 places welfare and consumption in a new setting. Past investment tools require reassessment. Completed outcomes remain distinct from future plans.', ['poverty-report', 'wb-2026']),
  ],
  'xinjiang-rights': [
    d('安全背景与不可集体归责', 'Security context without collective blame',
      '新疆有多民族、宗教和跨境联系的复杂历史，暴力袭击造成平民伤亡，政府有保护公众的责任。反恐背景应具体记录实施者与事件，不能把维吾尔族、其他穆斯林或持宗教习惯的人整体视为潜在罪犯。国家安全需要证据，身份本身不能代替个人违法事实。\n\n地区发展、就业和交通改善是真实研究对象，也不能回答拘禁是否任意、宗教自由是否受损的全部问题。把经济成果与权利伤害并列说明，不是以收益抵销伤害。不同民族、性别、代际和城乡居民的经历有差异，不能用单一声音代表整个新疆。',
      'Violent attacks caused civilian harm and create a duty to protect, but ethnicity and religious practice do not establish individual guilt. Security requires evidence.\n\nDevelopment and rights need separate assessment: economic gains do not resolve arbitrary detention claims. Residents’ experiences vary across communities and social positions.', ['xinjiang-ohchr', 'xinjiang-response']),
    d('2017年前后拘禁体系的扩大', 'Expansion of detention around 2017',
      '2017年前后以反恐和去极端化为名的拘禁及职业教育培训体系明显扩大，人员进入和离开的自愿性、法律依据与期限成为核心问题。政府称其提供技能和预防极端主义，联合国评估及相关证言则指出广泛任意拘禁和严厉限制。名称不能决定真实羁押性质。\n\n判断需考察居民能否自由离开、是否有律师与司法复核、受拘理由是否基于具体行为。不能因设施有教室就推定不是拘禁，也不能把所有教育活动都称为同一制度。具体时期与设施差异仍需资料，公共证据限制应保留，但不消解已经能够确认的严重模式。',
      'Around 2017, detention and vocational-training systems expanded. Voluntariness, legal grounds and duration are central. Government training claims contrast with documented arbitrary detention; labels do not determine custody conditions.\n\nFreedom to leave, counsel, review and individualized grounds matter. Evidence gaps and facility variation coexist with established serious patterns.', ['xinjiang-ohchr', 'xinjiang-response']),
    d('2022年联合国评估怎样形成', 'How the 2022 UN assessment was framed',
      '联合国人权高专办2022年评估结合访谈、法律政策、公开文件及政府回应，判断新疆发生严重人权侵犯，任意和歧视性拘禁程度可能构成国际罪行，特别是危害人类罪。这里的“可能构成”是法律评估表述，并非国际法院已经审结并判定每个具体人的刑事责任。\n\n访谈样本、取得材料和现场访问存在限制，报告自身说明证据和方法。方法限制需要理解，不意味着所有结论与未经核实宣传同等。阅读时应同时看原文、依据和结论范围，不把标题缩成一个标签，也不省略已经明确指出的严重侵害。',
      'OHCHR’s 2022 assessment used interviews, policy and documents with government responses. It found serious violations and said arbitrary, discriminatory detention may constitute international crimes, particularly crimes against humanity. This was not a final criminal judgment against individuals.\n\nMethod and access limits require attention without equating supported findings with unsupported propaganda.', ['xinjiang-ohchr']),
    d('政府回应及如何评价回应', 'The government response and its assessment',
      '中国政府否认评估的主要结论，强调反恐、去极端化、职业培训和发展成就，并质疑材料来源与政治动机。回应全文由联合国网站同时提供，读者应能直接查看。准确陈述政府立场是叙述完整性的要求，不代表它自动推翻独立证据。\n\n评价回应需要逐项核对法律、设施、个人经历和统计，而非只按双方机构身份选择信任。安全改善即使得到证实，也不能使酷刑、任意拘禁或歧视成为合法手段；反过来，严重指控仍要遵守证据标准。不同结论的支持强弱应清楚呈现，不作机械的五五分配。',
      'China rejected major findings, stressing security, training and development and disputing evidence and motives. The UN-hosted response allows direct reading. Recording it does not automatically rebut independent evidence.\n\nClaims need point-by-point assessment. Improved security would not legalize torture or arbitrary detention, and grave allegations still require evidence. Neutrality is not equal weight for unequally supported claims.', ['xinjiang-response', 'xinjiang-ohchr']),
    d('宗教、家庭与劳动问题', 'Religion, families and labor',
      '拘禁以外，宗教实践、文化与语言、家庭分离、隐私和劳动安排也进入评估。对亲属失联的担忧不能仅用设施关闭或人员结业解释，居民还需要知道亲人下落、是否有自由与获得救济的渠道。家庭照护与儿童生活是权利影响的重要部分。\n\n劳动项目是否强迫，需要核查能否拒绝、是否受威胁、工资和行动自由，不能仅由有工资或签署合同认定自愿。统计和供应链调查具有范围限制，具体产品与地区应分开。本书不把未核实总人数或产业比例作精确图表，而以证据类型和制度问题呈现。',
      'The assessment also concerns religion, culture, family separation, privacy and labor. Closure or graduation claims do not alone resolve relatives’ whereabouts and liberty.\n\nConsent in labor requires the ability to refuse without threat, alongside pay and movement. Contracts or wages alone do not establish voluntariness. Product-specific evidence should not be generalized without limits.', ['xinjiang-ohchr', 'xinjiang-response']),
    d('2026年前的研究边界', 'Research boundaries through the cutoff',
      '政策和设施可能随时间调整，2017年的证据不能直接代表2026年每一处现实。调查进入、档案和自由访谈不足，使追踪长期后果困难；对已经发生的侵害，时间过去也不能替代问责。应持续区分过去拘禁、目前刑事羁押、就业与监控等不同状态。\n\n国际制裁、供应链规则和外交争论使材料环境更政治化，受害者声音尤其容易被国家竞争遮蔽。研究需要保护个体、核实身份并避免暴露无关隐私。本书截至资料截止日不宣称掌握全部实时状况，也不因更新困难删去已经有充分依据的重要事件。',
      'Earlier evidence cannot describe every current facility. Restricted access complicates tracking, while elapsed time does not remove accountability. Detention, imprisonment, employment and surveillance are distinct statuses.\n\nInternational disputes can obscure affected people. This account protects privacy and distinguishes established past findings from unavailable real-time knowledge.', ['xinjiang-ohchr', 'xinjiang-response']),
  ],
  'leadership-2012': [
    d('领导交接与权力重组', 'Succession and concentration of authority',
      '2012年中共十八大后习近平任总书记，随后出任国家主席，党、国家和军队职位相互结合。此前形成的任期与接班惯例提供背景，但非所有惯例都等于明确法律。新时期中央协调机构、党内纪律和人事安排加强集中统一，政策执行和信息反馈方式随之改变。\n\n权力集中可能加快跨部门行动，也减少不同意见公开表达和制度制衡空间。评价需要具体观察决策速度、纠错和责任，而非只用强势或效率作整体判断。普通干部、企业和公民对政策预期的变化，是领导体制如何进入社会的重要路径。',
      'Xi became party general secretary in 2012 and later state president, combining party, state and military authority. Formal law and succession conventions were not identical.\n\nConcentration could improve coordination while narrowing dissent and checks. Decision speed, correction and accountability require evidence beyond leadership style.', ['constitution', 'amendment-2018']),
    d('反腐的治理与政治作用', 'Governance and political roles of anticorruption',
      '反腐回应公众对贪污、特权和权力交易的不满，处理高层与基层官员，改变干部行为和利益网络。查处真实腐败具有公共价值，反腐同时也重组政治联盟与组织控制。不能因具有政治作用就认定所有案件虚假，也不能因存在犯罪就忽略调查程序。\n\n纪律调查与司法审判有不同权限和证据要求，后续监察体制扩大覆盖范围。调查对象的辩护、羁押和复核是评价的重要内容。以运动压力减少某些交易，不必然建立长期透明、利益申报和独立监督；效果需看制度能否持续约束所有掌权者。',
      'Anticorruption addressed real public concerns and changed political networks. Governance value and political consolidation can coexist; neither makes all cases false or every procedure acceptable.\n\nDiscipline, supervision and criminal trial have differing authority. Durable transparency and review matter beyond campaign intensity.', ['constitution', 'amendment-2018', 'political-violence']),
    d('2018年修宪的准确范围', 'The precise scope of the 2018 amendment',
      '2018年修宪取消国家主席、副主席连续任职不得超过两届的规定，并将相关政治思想及监察委员会等内容纳入宪法。取消的是特定国家职务的明文限制，不能说此前总书记也有相同宪法两届条款。实际最高权力来自多个职位和党内结构，文本与政治惯例共同影响接班。\n\n政府支持者强调连续领导与治理需要，批评者担忧权力集中和接续不确定性。两类观点应说明依据，并检验实际制度约束。修宪按正式程序通过与公众能否自由讨论其意义，是两个不同评价层次，不能以其中一项自动回答另一项。',
      'The 2018 amendment removed the explicit two-consecutive-term limit for state president and vice president and added supervisory institutions and political language. The party general secretary had no identical constitutional clause.\n\nArguments for continuity and concerns about concentration need institutional assessment. Formal passage and freedom to debate are separate questions.', ['amendment-2018', 'constitution']),
    d('党政、市场与社会组织', 'Party, state, markets and civic organizations',
      '党的领导在国家机关、企业和社会组织中获得更突出制度表达，安全与发展目标更加紧密结合。市场继续承担商品和资源配置作用，国家产业政策、监管和组织领导又加强，不能把现实简化为完全计划或完全市场。\n\n企业面对创新机会与政策边界，社会团体和公民表达面对更强管理。监管可以处理垄断、金融和数据风险，其程序、可预测性及对异议的限制也需分别评价。治理成效不应只看宣布多少行动，还要看是否保护个人、允许反馈并减少不必要的不确定性。',
      'Party leadership gained stronger institutional expression across government, business and civic life. Markets persisted alongside industrial policy and security priorities.\n\nRegulation can address genuine risks while requiring predictable procedures and protected feedback. Announced activity alone does not establish public benefit.', ['constitution', 'amendment-2018', 'ai-rules', 'wb-2026']),
    d('政策动员与社会承受能力', 'Mobilization and social capacity to bear policy',
      '脱贫、环境治理和疫情应对显示集中动员可以迅速投入资源，也可能带来层层加码、指标替代目标和基层避责。地方并非完全被动，仍会解释中央信号并在考核中选择策略。必须追踪具体领域，而非认定集中就必然成功或必然失败。\n\n家庭和企业承担政策调整成本，若缺少申诉与纠错，短期措施可能持续过久。公共参与和真实信息是治理资源，而不仅是需要控制的风险。对某项政策后来的修正，应同时承认改变与分析为何此前难以反馈，避免把所有后果归给少数执行者。',
      'Poverty, environmental and pandemic campaigns showed rapid resource mobilization alongside target distortion and local overimplementation. Local discretion remained consequential.\n\nHouseholds bear adjustment costs. Appeals and candid information help correction; later policy change requires examining why earlier feedback failed rather than blaming implementers alone.', ['poverty-report', 'climate-ndc', 'who-timeline', 'constitution']),
    d('延续到2026年的观察方法', 'Observing developments through 2026',
      '当代领导史容易被宣传成就或即时政治反应主导，本书以已发生的任职、修法、政策与可核查影响为基础。对领导动机的推断应标明，未公开的内部讨论不能用想象补齐。公开讲话是立场证据，不等同于政策实现或真实私人意图。\n\n增长、国家能力、权利和社会信任不是可以合成一个分数的指标。2026年尚未结束，全年经济、人口和未来人事不应预先定论。资料截止日以后事项留待增补，当前叙述保留已知事实和不确定边界，让读者能够检验而不是只能接受结论。',
      'Contemporary leadership history should rest on documented appointments, law and policy. Inferred motives and unavailable internal discussion remain marked; speeches establish positions rather than outcomes or private intent.\n\nGrowth, rights and trust cannot be collapsed into a score. Incomplete 2026 data and future personnel decisions are not presented as settled history.', ['constitution', 'amendment-2018', 'wb-2026', 'nbs-2025']),
  ],
  'belt-and-road': [
    d('2013年倡议与多样化项目', 'The 2013 initiative and diverse projects',
      '2013年提出丝绸之路经济带与海上丝绸之路，随后成为覆盖基础设施、贸易和融资合作的广泛倡议。铁路、港口、电力和通信项目在不同国家采取不同合同和资金结构，不能把贴有一带一路名称的项目都看成同一中央计划。部分项目此前已经酝酿，后来纳入倡议。\n\n中国政府、政策银行、商业银行、国企和私人企业角色不同，东道国政府也主动提出建设需求。地方政治、商业利益和战略考虑相互交织，不能把合作国家当成没有自主性的对象。理解某项目，需要从立项、招标、融资和运营逐步追踪。',
      'The 2013 land and maritime initiatives grew into a broad framework for infrastructure and finance. Projects differed in contracts, funding and prior origins.\n\nChinese institutions and host governments had distinct roles. Host states also initiated demand; project histories require tracing approval, procurement, finance and operation.', ['bri-economics']),
    d('运输成本与条件性收益', 'Transport costs and conditional gains',
      '交通改善可能缩短运输时间、连接内陆和扩大市场，但世界银行2019年报告中的潜在收益来自情景模型，依赖贸易便利化、竞争和政策配套。模拟中可能增加的贸易或收入不是已经实现的统计，也不能推广到所有参与国家。\n\n一条铁路是否有用取决于货源、票价、维护、边境手续和与其他交通方式的连接。建设里程是投入指标，不等于社会净收益。模型可以帮助提出条件与风险，实际评价仍需运营数据、当地企业和居民经验，避免用漂亮线路图取代成本收益分析。',
      'Transport can reduce time and connect markets, but the World Bank’s 2019 scenarios describe conditional potential, not realized totals.\n\nDemand, pricing, maintenance, border procedures and network links determine value. Mileage measures construction rather than net welfare. Operational evidence must complement models and route maps.', ['bri-economics']),
    d('债务、合同与东道国选择', 'Debt, contracts and host-country choices',
      '贷款支持长期项目，也可能在收入不足、汇率变化或财政恶化时增加偿付压力。债务可持续性需要把所有债权人、项目现金流和公共预算合并考察，不能因为某笔中国贷款存在就推定全部危机由中国造成；同样，借款由东道国签署也不使贷方尽调责任消失。\n\n合同透明度、担保、重新谈判和资产安排决定风险分担。所谓债务陷阱的笼统标签与完全互利的宣传都不足以解释每个案例。应检验当时信息、可行替代和后来结果，区分设计不足、商业失败、政治腐败及外部冲击。',
      'Loans can fund development and create repayment stress through weak revenue, currency or fiscal shocks. Sustainability includes all creditors and budgets; host approval does not remove lender diligence.\n\nTransparency, guarantees and renegotiation shape risk. Neither a universal debt-trap label nor universal mutual benefit explains every case.', ['bri-economics', 'wb-2026']),
    d('劳动、土地与环境', 'Labor, land and environment',
      '工程带来就业、道路与电力，也可能涉及征地、迁移、生态破坏和劳动条件争议。使用中国或当地工人并不能单独判断收益分配，需要看工资、技能转移、安全和当地采购。受益的城市企业与失去土地的农村家庭可能不是同一群人。\n\n环境影响评估、公众咨询和申诉渠道关系项目正当性，不能等到开工后才把居民意见视为阻碍。跨国承包增加责任追踪难度，资金方、承包方和东道国政府各有义务。保护弱势居民不是合作的附属装饰，而是长期运营和社会信任的基础。',
      'Projects can create jobs and services while causing land loss, ecological harm and labor disputes. Worker nationality alone does not measure wages, skills or local procurement.\n\nConsultation, assessment and remedies matter before construction. Financiers, contractors and host authorities retain distinct duties across borders.', ['bri-economics']),
    d('战略影响与第三方竞争', 'Strategic influence and third-party competition',
      '港口、交通和技术标准可能增加中国经济与外交影响，也引发其他国家对安全和依赖的担忧。商业设施并不自动等于军事基地，潜在军民两用也不能被完全忽略。每项判断需要地点、控制权、使用协议和实际行为依据。\n\n美国、欧洲、日本等提出不同合作方案，参与国可能利用竞争争取条件，而非只能选择一方。跨国公共产品与地缘竞争同时存在，不能用战略动机否认所有发展收益，也不能以发展为名拒绝检查权力不平等。长期结果取决于合同、治理和当地政治。',
      'Infrastructure and standards can increase influence and security concerns. Commercial facilities are not automatically military bases; dual-use claims require specific control and conduct evidence.\n\nHost states may negotiate among competing partners. Development and geopolitical competition coexist, with outcomes dependent on governance and contracts.', ['bri-economics']),
    d('从规模扩张到可持续性', 'From expansion to sustainability',
      '后续合作更加关注项目质量、风险和绿色发展，债务调整及全球经济变化影响新项目节奏。政策口号转向不说明所有旧风险已经解决，项目取消也不证明整体倡议没有价值。应逐项观察完成、运营、重谈和失败，不把签约金额当成实际投资。\n\n截至资料截止日，一带一路仍是持续过程，没有统一最终成绩单。公开数据库的项目范围和纳入规则不同，比较需保留年份与方法。本书以可核查机制和条件解释为主，未来补充个案时将同时呈现当地受益、反对意见及合同证据，避免只从出资国视角叙事。',
      'Later emphasis on quality and greener projects operated amid debt adjustment and global change. Announcements, commitments and actual investment differ; individual failures do not settle the entire initiative.\n\nThe process remains ongoing. Databases use differing coverage, so future cases require local perspectives and contract evidence alongside financier narratives.', ['bri-economics', 'wb-2026', 'climate-ndc']),
  ],
  'digital-society': [
    d('从联网到平台基础设施', 'From connectivity to platform infrastructure',
      '互联网、移动通信、电子商务和数字支付改变信息、购物与劳动组织，平台逐渐成为生活基础设施。变化来自网络建设、企业创新、用户采用和国家政策共同作用，不是技术自动决定社会。城乡、年龄和收入差异决定谁容易接入，数字便利也可能使不会使用者更难取得服务。\n\n平台连接商家、消费者、司机和骑手，网络效应使规模优势持续扩大。低价与方便可能伴随劳动强度、商家依赖和市场集中，消费者收益与劳动者处境需要一起观察。总交易额是经济活动指标，不能直接表示公平、隐私或个人自由增加。',
      'Connectivity, commerce and payments became infrastructure through networks, firms, users and policy. Access differed by age, income and residence.\n\nNetwork effects increased concentration. Convenience coexisted with worker pressure and merchant dependence; transaction volume does not measure fairness or privacy.', ['nbs-2025', 'wechat-research', 'reform-development']),
    d('数据收集与商业权力', 'Data collection and commercial power',
      '搜索、推荐、定位和信用服务依赖数据，用户往往难以了解收集范围、保存时间和跨机构使用。点击同意不必然体现充分理解，尤其在服务不可替代或条款复杂时。企业提高效率与用户数据控制之间存在需要制度解决的张力。\n\n个人信息、公共安全和商业竞争有不同规则目标，监管既可限制滥用，也可能扩大国家取得数据的能力。评价应看最少必要收集、透明度、删除更正和救济，而不是只问数据是否留在本国。国家与企业都掌握权力，隐私不能仅在两者之间转移而视作问题已解决。',
      'Search, recommendation and location services depend on data that users may poorly understand. Formal consent is weaker where alternatives are unavailable.\n\nCommercial regulation may also expand state access. Necessity, transparency, correction and remedies matter beyond data nationality; moving power between firms and the state does not itself secure privacy.', ['wechat-research', 'constitution', 'ai-rules']),
    d('审查的实验性证据', 'Experimental evidence of censorship',
      '多伦多大学Citizen Lab通过技术实验研究微信等平台的内容控制，发现境外注册账号之间传送的某些文件也会被用于建立针对中国注册账号的审查机制。研究通过设计比较推断系统行为，比只凭一条消息发不出更有解释力。\n\n结论有测试时间、账号和内容范围，不能扩展为每次通信均以同样方式处理，也不能把技术证据直接等同某位用户被人类逐条阅读。审查、监测、删除和账户处罚是不同过程，应准确使用。资料公开方法使读者能够检查推理，同时保留平台后来更新的可能。',
      'Citizen Lab experiments found that some files exchanged among non-China-registered WeChat accounts helped populate censorship for China-registered users. Controlled comparisons supported inference.\n\nTime, accounts and content limit generalization. Surveillance, blocking and account punishment differ, and system evidence does not prove a human read every message.', ['wechat-research']),
    d('信息控制与公共危机', 'Information control during public crises',
      '疫情等危机中，谣言治理、风险沟通与政治审查可能重叠。删除明显虚假医疗信息有公共目的，限制真实求助和合理批评则会损害预警与信任。Citizen Lab对2020年初平台的测试记录了相关控制，但不能代表所有平台、年份和具体删除原因。\n\n公众缺少可靠信息时更易传播未经核实消息，国家与平台应提供解释和纠错，而非只增加惩罚。被删内容需要独立核实，删除本身不证明其真实，也不证明其虚假。研究应连接技术规则、人工执行和政治环境，让信息史超出简单的有网或没网。',
      'Crisis moderation can mix falsehood control with political censorship. Blocking genuine appeals can damage warning and trust. The 2020 tests had limited platform and temporal scope.\n\nDeletion proves neither truth nor falsehood. Reliable explanation and correction complement moderation, and technical rules must be linked to implementation and politics.', ['covid-censorship', 'who-timeline', 'wechat-research']),
    d('平台劳动与算法管理', 'Platform labor and algorithmic management',
      '派单、评分和路线系统提高匹配效率，也可能压缩劳动者可控制的时间和收入。司机、骑手、主播与内容工作者的劳动关系不同，不能把所有平台就业当成同一种自由职业。灵活性有真实价值，职业伤害、社会保险和申诉不足也有真实成本。\n\n算法不是脱离组织的自然力量，企业目标、数据选择和劳动规则决定其效果。评价需要观察工人能否理解考核、拒绝危险任务和质疑错误。消费者追求即时服务的习惯也进入压力链，公共政策应使便利与保护相容，而不是要求劳动者自行承担全部风险。',
      'Dispatch and rating systems improved matching while restricting control over time and income. Platform occupations differ; flexibility and insecurity coexist.\n\nAlgorithms implement organizational choices. Understandable evaluation, refusal of unsafe tasks and appeals matter, as do consumer expectations and social insurance.', ['nbs-2025', 'reform-development', 'constitution']),
    d('生成式AI进入社会治理', 'Generative AI and social governance',
      '生成式人工智能扩大文本、图像和代码生产，带来科研与教育机会，也产生幻觉、隐私、偏见及责任分配问题。模型输出流畅不等于事实可靠，自动化评估也需真实有效的测量。技术发展史应记录能力、应用与失败，而非只按参数规模排列成就。\n\n2023年生成式人工智能服务管理暂行办法规定服务责任、内容和数据等要求，法律目标与执行效果需要区别。安全保障、创新空间和表达限制可能发生张力，必须具体分析。本站历史正文与图表仍以可核查来源为基础，不把AI生成内容当作独立史料。',
      'Generative AI expanded production alongside hallucination, bias, privacy and accountability problems. Fluent output is not verification, and evaluation needs valid measures.\n\nThe 2023 interim rules establish service requirements, whose aims and outcomes differ. Safety, innovation and expression require specific analysis. AI output is not treated here as independent historical evidence.', ['ai-rules', 'constitution']),
  ],
  'hongkong-protests': [
    d('2014年雨伞运动与政改争议', 'The Umbrella Movement and electoral reform',
      '2014年围绕行政长官选举方案的争议引发占领和雨伞运动，参与者要求更具实质竞争的普选。中央强调提名与国家安全框架，香港不同社会群体对策略、秩序和未来有分歧。运动不是所有香港居民的一致选择，也不是仅由外部力量可以解释的现象。\n\n长期住房、机会和身份问题影响社会气氛，但不能把明确政治诉求全部还原为经济不满。和平占领、个别冲突和政府执法需要分别记录。未能达成改革使不信任累积，后来的运动沿用经验又形成不同组织方式，不能把2014与2019简单合并。',
      'Disputes over the chief-executive election framework prompted the 2014 occupations. Participants sought meaningful electoral choice; central authorities emphasized nomination and security. Views within Hong Kong differed.\n\nEconomic pressures did not erase explicit political demands. Occupation, violence and policing require separate treatment, and 2014 and 2019 were distinct movements.', ['hongkong-declaration', 'hongkong-policy-2020']),
    d('2019年修例与诉求扩大', 'The 2019 bill and expanding demands',
      '2019年逃犯条例修订引发大规模反对，公众担心移交安排影响司法保障。政府先暂缓、后撤回法案，过程中诉求扩大到警务问责、被捕者、运动定性和选举。撤回时间与抗议延续之间存在因果和信任问题，不能因最后撤回就认为最初反对没有对象。\n\n参与者包括和平游行者、较激进抗议者与不同职业群体，组织呈去中心化特点。意见也不断变化，不能把某一口号当所有人的固定纲领。政府关于外部干预的主张需要具体证据，公众真实不满不应被一概排除。',
      'The extradition bill raised concerns about legal protection. Suspension and eventual withdrawal came amid widening demands over policing and representation. Timing and trust help explain continued protest.\n\nDecentralized participants and strategies varied. Claims of outside interference require evidence rather than erasing local grievances.', ['hongkong-policy-2020', 'hongkong-declaration']),
    d('暴力、警务与一致标准', 'Violence, policing and consistent standards',
      '部分抗议者实施破坏、纵火和袭击，警察使用催泪弹及其他武力，严重伤害与争议事件需要逐件核查。记录抗议者暴力不使所有参加者成为罪犯，记录警务滥用也不表示任何抗议行为都正当。行为、指挥和调查责任应分开。\n\n国家掌握执法权，对必要性、比例和程序负有特殊责任，不能用双方发生冲突就认定责任自然相等。独立调查和可追责证据有助恢复信任，未经核实影像与传闻不应直接作定论。本书避免用最极端片段代表数月内全部公众行动。',
      'Some protesters used arson, attacks and destruction; police used tear gas and other force. Each incident needs verification. Neither side’s misconduct defines every participant.\n\nState power carries particular proportionality and procedural duties. Independent inquiry and contextualized evidence are preferable to treating extreme clips as the whole movement.', ['hongkong-policy-2020', 'hongkong-un-experts', 'constitution']),
    d('2020年国安法与制度转向', 'The 2020 National Security Law',
      '2020年香港国安法通过并实施，设立新的罪名、执法和司法安排。政府强调结束暴力、堵塞国家安全漏洞和恢复稳定，批评者及人权专家关注定义、程序和表达空间。两种论点需要与法律文本和具体案件比较，而不是只按立场选择。\n\n传媒、社团和政治组织空间随后改变，个人对言论与参与风险的判断也变化。秩序恢复与自由受限可以同时发生，应分别衡量；不能把抗议减少直接当成所有人认同，也不能用某项安全目标否认具体程序问题。',
      'The 2020 law changed offenses, enforcement and courts. Government stabilization arguments and rights concerns require comparison with text and cases.\n\nMedia and civic space changed, affecting perceived participation risk. Reduced protest does not alone establish consent; order and restricted freedoms may coexist.', ['hongkong-policy-2020', 'hongkong-un-experts']),
    d('选举变化与2024年本地立法', 'Electoral changes and the 2024 ordinance',
      '后续选举制度调整强调爱国者治港，候选资格和代表结构变化，需要与回归初期及2010年代制度分别比较。2024年维护国家安全条例于3月23日生效，落实基本法第二十三条本地立法，与2020年法律是不同文件，不能混称为同一次通过。\n\n香港政府强调必要性和法律保障，联合国专家通信提出条款宽泛及权利影响关切。专家意见不是法院终审判决，政府保证也不是实际效果的独立证据。应持续观察案件、程序及新闻学术活动，而非在公布当天就预设所有未来结果。',
      'Electoral redesign changed eligibility and representation. The Safeguarding National Security Ordinance took effect on 23 March 2024 and is distinct from the 2020 law.\n\nGovernment assurances and UN expert concerns have different evidentiary status; neither settles every future case. Implementation requires continued observation.', ['hongkong-2024', 'hongkong-un-experts', 'hongkong-policy-2020']),
    d('迁移、信任与社会延续', 'Migration, trust and continuing society',
      '政治变化、疫情和经济条件共同影响移民、人才与家庭决定，不能把每次离开都归为政治逃离，也不能忽视明确因自由和制度担忧而离开的声音。留下者可能出于责任、资源或认同，不能简单视为被动接受。家庭跨境生活改变学校、照护和职业安排。\n\n香港仍有复杂经济和公共生活，政治变化不是全部城市史，却深刻影响参与与信任。未来增补需要纳入普通劳动者、移民和不同政治立场居民，以具体经验检验官方稳定叙述与社会损失论述。资料截止日前的事实和之后尚未完成的变化应保持分界。',
      'Politics, the pandemic and economic conditions shaped migration, with varied motives for leaving and remaining. Transnational families reorganized work and care.\n\nHong Kong’s economy and everyday life continued amid changed participation and trust. Later additions require varied residents’ experiences and clear cutoff boundaries.', ['hongkong-policy-2020', 'hongkong-2024', 'hongkong-un-experts']),
  ],
  'taiwan-strait': [
    d('2016年后的政治基础变化', 'Changing political foundations after 2016',
      '蔡英文2016年就任后，两岸对共同政治基础的认定出现更大分歧。大陆要求承认体现一个中国原则的基础，民进党政府强调台湾民主制度与维持现状，双方对既有表述的含义并不一致。交流机制受到影响，社会和商业联系却未立即消失。\n\n台湾内部对统独、身份和安全有多种观点，民进党、国民党及其他力量也随选举和形势调整立场。不能由一次投票推定所有选民都支持同一主权主张。大陆公众同样并非只有单一态度，但公开表达环境影响可见意见，比较民意需要注意方法与限制。',
      'After Tsai took office in 2016, disagreement over a shared political basis widened. Beijing emphasized one-China foundations; the DPP government emphasized democracy and the status quo. Social and business ties persisted despite disrupted mechanisms.\n\nElectoral choices do not identify every voter’s sovereignty preference. Public opinion on both sides requires attention to survey design and expression conditions.', ['taiwan-tsai', 'taiwan-republic', 'taiwan-whitepaper-2022']),
    d('2022年白皮书的大陆立场', 'The mainland position in the 2022 white paper',
      '大陆2022年白皮书重申台湾是中国一部分、实现统一及一国两制政策，同时表示不承诺放弃使用武力，称相关措施针对外部干涉和少数分裂势力。准确记录这些主张，有助理解政策及安全信号，但不能把官方文本当成台湾居民已经接受的安排。\n\n历史、法律与民族叙事在文本中结合，读者应区分政府立场和已获各方共同确认的事实。反对外部干预的理由不能自动回答居民同意、权利与战争后果问题。评价任何用武选项都需审视必要性、国际法、平民保护及替代办法，而非只依据民族目标。',
      'The 2022 white paper reaffirmed reunification and one country, two systems while declining to renounce force. Recording this position does not establish Taiwanese consent.\n\nHistorical and legal claims require separation from agreement. Any force option needs assessment of law, necessity, civilian protection and alternatives, beyond national objectives.', ['taiwan-whitepaper-2022', 'un-2758']),
    d('2024年选举与赖清德演说', 'The 2024 election and Lai’s address',
      '赖清德2024年当选并于5月就任，执政党与立法院力量分布不同，反映台湾选民在不同选票上的选择。就职演说表达维护民主、和平与既有政治体制的立场，大陆则对其两岸表述提出批评。演说是当事方立场证据，不是区域地位已经取得共同结论。\n\n外交政策与岛内治理相连，军费、能源、住房及议会监督都会影响公众判断。不能将每项政策争议都还原为统独，也不能因选举合法举行就忽略其后治理问题。读者应能比较各方原文，而不是只接收摘要中的对抗性标签。',
      'Lai’s 2024 election and May inauguration occurred with a different legislative balance. His address stated democratic and peace positions, disputed by Beijing; it did not settle regional status.\n\nSecurity choices interact with budgets, energy and domestic accountability. Not every policy disagreement reduces to sovereignty, and electoral legitimacy does not end scrutiny.', ['taiwan-lai', 'taiwan-inauguration', 'taiwan-elections', 'taiwan-whitepaper-2022']),
    d('军演、灰色地带与误判', 'Exercises, gray-zone pressure and miscalculation',
      '军事演习、海空活动与对外安全合作改变风险感知，威慑、训练和政治信号可能同时存在。活动次数增加不必然表示战争已经决定，未发生战争也不说明风险虚假。具体事件需要标明地点、日期、规模和来源，避免把所有飞行都称作进入领空。\n\n领空、领海、防空识别区和海峡中线不是相同法律概念，示意图应明确类别。危机沟通、海空相遇规则和政治表态影响误判，居民与航运承担不确定性。安全分析不能只看武器数量，也需比较意图、预警、补给和可能的升级链。',
      'Exercises and security cooperation combine deterrence, training and signaling. Activity does not prove a decision for war, while peace does not erase risk.\n\nAirspace, territorial waters, identification zones and the median line differ. Communication and encounter rules affect escalation; counts of weapons alone cannot describe the danger.', ['taiwan-whitepaper-2022', 'taiwan-inauguration', 'rapprochement-frus']),
    d('经济联系与社会选择', 'Economic connections and social choices',
      '贸易、投资、学生与家庭联系使两岸相互依赖，也可能形成不对称压力。经济交流不自动产生相同国家认同，限制交流也不必然提高安全。企业根据市场和政策分散风险，劳动者与跨境家庭承担调整，不能只从总贸易额理解关系。\n\n半导体等产业增加台湾国际重要性，也可能加深安全竞争和供应链焦虑。技术优势不是保证和平的单一保险，产业迁移也并非必然导致某种政治结果。研究应将商业决策、国家管制和居民偏好分开，让社会主体不被军事和外交叙述完全遮蔽。',
      'Trade and family links create interdependence and asymmetric pressure without automatically aligning identity. Firms diversify while workers and families absorb adjustment.\n\nSemiconductors increase strategic importance without guaranteeing peace or predetermining politics. Commercial, regulatory and social choices require separate analysis.', ['taiwan-republic', 'trade-review', 'chip-controls']),
    d('外交措辞与未来边界', 'Diplomatic wording and the future boundary',
      '不同国家的一个中国政策、中华人民共和国的一个中国原则及台湾政府主张并非完全相同，承认、认知与支持等措辞需要依据具体文件。联合国代表权也不能自动替代台湾最终地位的全部法律讨论。解释这些差异，是准确叙述而非有意模糊立场。\n\n本书截至资料截止日不预判统一、独立或战争结局，也不将尚未发生的2026年后事件列入编年事实。以和平、居民权利和一致证据标准检验各方行为，允许读者看到真实分歧与可选择路径，避免将灾难写成不可避免的历史命运。',
      'National one-China policies, Beijing’s principle and Taiwan’s claims are not identical. Recognition language and UN representation require precise documents.\n\nNo future sovereignty or war outcome is presented as inevitable. The account applies peace, residents’ rights and consistent evidence through the cutoff date.', ['un-2758', 'rapprochement-frus', 'taiwan-inauguration', 'taiwan-whitepaper-2022']),
  ],
  'trade-tech-conflict': [
    d('从经贸争议到2018年关税', 'From trade disputes to the 2018 tariffs',
      '中美在市场准入、补贴、知识产权和技术转让上的分歧长期存在，2018年美国依据国内301调查实施关税，中国采取反制。美方政策理由反映本国法律与战略判断，不等于世界贸易组织已裁定全部主张；中方关于公平与发展权的回应也需与具体规则核对。\n\n关税对进口商、消费者、出口企业和工人影响不同，法定缴纳主体与最终经济负担不能混同。第三国可能获得订单，也面临规则变化。将争端写成两国领导人个人争吵，会遗漏国内产业、选民与跨国企业的利益，以及全球生产网络已形成的相互依赖。',
      'Longstanding disputes led to US Section 301 tariffs in 2018 and Chinese retaliation. Domestic-policy findings are not equivalent to comprehensive WTO judgments.\n\nLegal tariff payment and ultimate economic incidence differ. Consumers, firms, workers and third countries experienced uneven effects, beyond leaders’ personal conflict.', ['trade-301', 'trade-review', 'wto-accession']),
    d('谈判、采购承诺与持续关税', 'Negotiation, purchase commitments and persistent tariffs',
      '后续谈判形成阶段性协议和采购安排，缓和部分争议，却没有取消所有关税和结构问题。承诺金额、实际采购与疫情等外部冲击需要分别分析，不能因签署协议就认为争端结束，也不能因未完全实现目标就否认任何沟通效果。\n\n政策清单不断调整，豁免和产品分类使企业成本差异显著。研究某一年的影响必须使用当年有效规则，不能把最新税率倒用于2018年。政府公开解释提供立场证据，真实经济效果仍需价格、贸易转移、就业和企业数据共同检验。',
      'Partial agreements and purchase commitments did not eliminate all tariffs. Promises, realization and pandemic shocks require separation.\n\nExclusions and classifications changed firm costs over time. Historical analysis needs the rules then in force, with outcomes tested against prices, employment and trade rather than official justification alone.', ['trade-301', 'trade-review']),
    d('2022年半导体出口管制', 'The 2022 semiconductor controls',
      '美国2022年10月加强先进计算和半导体制造相关出口管制，强调国家安全及军事用途风险。规则涉及产品、设备、最终用途和人员活动等不同对象，不能简化为所有芯片都禁止出口。后续版本另有变化，本书引用2022年文件时不声称它涵盖2026年全部现行规则。\n\n中国强调技术自主和产业链安全，企业寻找替代、储备与研发。管制可能延缓某些能力，也激励替代和增加成本，最终效果取决于技术、盟友执行和创新。宣布限制不等于已经完全阻断技术，取得突破也不等于全部供应依赖消失。',
      'October 2022 controls targeted advanced computing and manufacturing through varied product, end-use and activity rules, not a ban on every chip. Later versions require separate verification.\n\nChina pursued substitution and autonomy. Delay, innovation and added costs can coexist; neither a restriction nor a breakthrough settles all dependencies.', ['chip-controls', 'trade-review']),
    d('企业调整与供应链重组', 'Firm adaptation and supply-chain restructuring',
      '企业通过迁移部分生产、增加库存、改变供应商或设置区域体系分散风险，贸易流向变化不一定表示全部产能离开中国。最终组装转移与零部件、设备和管理仍来自原网络，可以同时发生。海关原产地与完整增加值来源也不相同。\n\n新设工厂影响当地就业，原工人和供应商承担调整成本，不能只按投资额比较胜负。企业也需兼顾市场、能源、物流和人才，政治风险是多种因素之一。所谓脱钩、去风险与产业升级应给出明确指标，避免用流行词概括所有复杂变化。',
      'Relocation, inventory and supplier diversification did not necessarily remove entire production networks. Customs origin differs from value-added sources.\n\nNew and old workers faced uneven adjustment. Market, energy and skills complemented political risk. Decoupling and de-risking need defined measures rather than slogans.', ['trade-review', 'reform-development', 'wb-2026']),
    d('安全、科研与开放的张力', 'Security, research and openness',
      '技术具有民用与军用交叉，国家对高风险用途可提出限制，但过宽管制也可能损害基础科研、人员交流和商业竞争。研究需要具体区分军民两用风险与一般国籍身份，避免把所有华人科学家视为安全对象，或把所有限制都看成纯粹商业保护。\n\n出口规则、投资审查和大学合作各有法律机制，不能混为一项政策。科研生态依赖国际知识流动，同时需要透明利益、数据保护和可追责合作。历史评价应检查实际风险减少与误伤，不能只以安全理由或开放原则其中一个词终止讨论。',
      'Dual-use risks can warrant controls, while overbreadth harms research and exchange. Nationality is not evidence of individual threat, and not every restriction is merely protectionism.\n\nExport law, investment screening and university rules differ. Evaluation requires both risk reduction and collateral harm, with accountable cooperation.', ['chip-controls', 'trade-review', 'ai-rules']),
    d('2026年的观察与未完成结果', 'Observations and unfinished outcomes in 2026',
      '截至资料截止日，关税与技术政策仍在演变，预测产业赢家或长期增长损失具有高度不确定性。本书保留已核查政策的年份，不编造全年贸易结果，也不由某个企业发布会推定国家整体技术地位已经逆转。\n\n评估长期影响需要生产率、消费价格、创新和安全等不同指标，利益也跨越国家边界。世界银行2026年更新提供宏观背景，预测并不是结算结果。未来增补将按具体新规则和实施证据更新，保留旧版本的历史环境，而不是用现行政策覆盖全部过去。',
      'Policies and outcomes remain evolving. Verified years are preserved, without invented full-year results or national conclusions from individual announcements.\n\nProductivity, prices, innovation and security differ. World Bank forecasts provide context rather than final outcomes; subsequent rules require dated updates.', ['trade-301', 'chip-controls', 'trade-review', 'wb-2026']),
  ],
  'covid-19': [
    d('2019年底预警与早期信息', 'Warnings and early information in late 2019',
      '2019年底武汉出现不明原因肺炎，医务人员、医院和公共机构逐步发现异常。早期病原和传播方式尚未完全明确，医生提醒、正式报告、公开通报与执法处理却有不同责任。对李文亮等人的训诫体现信息环境问题，不能用当时不知全部科学事实为压制合理警示作充分辩护。\n\n科学不确定性要求及时共享并修正信息，而不是保证最初判断永远不变。地方、中央和国际机构掌握情况有时间差，病毒溯源又是与早期应对责任相关但不同的问题。本书不把未经证实的起源假说写成事实，也不让溯源争论遮蔽可以调查的报告与决策过程。',
      'Wuhan’s unexplained pneumonia emerged in late 2019 amid incomplete knowledge. Clinical warnings, formal reporting, public disclosure and police action involved distinct duties; reprimanding reasonable warnings was not justified by scientific uncertainty.\n\nKnowledge should be shared and revised. Origin hypotheses and response accountability are related but separate, and unproven origins do not replace investigation of decisions.', ['who-timeline', 'covid-censorship']),
    d('2020年武汉封控与全国应对', 'Wuhan restrictions and the 2020 response',
      '2020年1月武汉交通封控后，全国通过病例隔离、接触追踪、社区管理和医疗扩容控制传播。医护、建设人员、志愿者与居民承担重大劳动，物资和医院压力在早期尤其严重。较早控制为部分地区争取时间，不能由此认为所有执行行为都无须审查。\n\n急救、慢性病、孕产和基本生活在限制中受到冲击，求助者处境与政策平均效果需要同时记录。社区互助和资源差异使居民经历不同。评价应分时期比较感染减少、医疗能力与非疫情伤害，不把每个阶段套成同一种封城模式。',
      'After Wuhan’s January restrictions, isolation, tracing, community controls and expanded care reduced transmission. Workers and residents carried substantial burdens.\n\nEmergency, chronic and maternity care also suffered. Mutual aid and resources shaped unequal experiences. Phase-specific benefits and indirect harm need joint assessment.', ['who-timeline', 'who-china-2023', 'covid-censorship']),
    d('动态清零的收益与条件变化', 'Dynamic zero COVID and changing conditions',
      '较长时间压低传播减少早期感染和死亡，为疫苗与医疗准备提供窗口。随着病毒变异、传播力增强及其他国家政策转变，原有措施的成本和可持续性变化。不能用2022年的条件评价2020年所有选择，也不能因早期有效就认定同样措施可以无限期延续。\n\n老年人疫苗覆盖、重症资源与基层服务决定退出风险，政策目标应与真实准备相连。检测与隔离规模扩大形成财政和执行激励，层层加码及不透明规则又削弱信任。保护生命的目标需要包含感染死亡，也包括延误医疗、心理与生计损害。',
      'Suppressed transmission reduced early harm and created preparation time. More transmissible variants changed cost and sustainability; neither retrospective rejection nor indefinite continuation follows automatically.\n\nOlder-adult vaccination and care capacity shaped exit risk. Testing incentives and overimplementation affected trust. Protection includes indirect health and livelihood harms.', ['who-timeline', 'who-china-2023', 'covid-excess-2023']),
    d('2022年封控中的生活冲突', 'Everyday conflicts during 2022 restrictions',
      '上海等地2022年长时间限制使食品、急诊、隔离安排和家庭分离成为公共争议。居民对感染风险与措施的态度不同，既有人担心放开，也有人难以承受继续限制。以统一标签称赞或责备所有居民，无法解释不同身体和经济条件。\n\n基层干部、配送员和志愿者在压力下执行政策，有真实付出，也有侵权和资源失配。责任需要追踪规则、考核、指挥和个别行为，不能把问题全部推给最后接触居民的人。公开投诉和真实信息本可帮助纠错，限制其传播会增加政策失明。',
      'Long 2022 restrictions raised disputes over food, emergency care, isolation and separation. Residents differed in infection risk and ability to bear controls.\n\nFrontline effort coexisted with abuse and misallocation. Rules and command chains matter alongside individual conduct; suppressing feedback can obstruct correction.', ['who-china-2023', 'covid-excess-2023', 'constitution']),
    d('白纸抗议与公共表达', 'White Paper protests and expression',
      '2022年11月乌鲁木齐火灾后，多地出现悼念和抗议，白纸成为表达审查与不满的象征。参与者诉求包括结束过度限制、获得表达空间及更广政治要求，并非所有人持有相同纲领。火灾具体救援责任与全国抗议缘由需要分别核查，不把未经充分证实的现场说法当定论。\n\n国际特赦组织后来访谈六名参与者，记录拘押、压力和创伤经历，这是明确归属的证言，不是全国随机样本或拘捕总数。和平表达应受到保护，个案仍需核查。抗议与随后政策变化时间接近，但不能仅凭先后顺序证明单一决定原因。',
      'After the November Urumqi fire, mourning and protests used blank paper to symbolize censorship and varied demands. Specific fire-response claims require their own verification.\n\nAmnesty’s six interviews provide attributed experiences, not representative totals. Peaceful expression merits protection. Temporal proximity to policy change alone does not establish one cause.', ['white-paper-testimony', 'constitution']),
    d('2022年底政策退出与感染潮', 'The late-2022 exit and infection wave',
      '2022年底防控快速放宽，感染和就医需求骤增，药品、医院和殡葬服务承受压力。退出本身回应旧措施不可持续的问题，退出速度、沟通与准备是否充分则属于不同评价。不能把批评突然退出理解为支持无限封控，替代路径包括分阶段准备和更可靠保护。\n\n高龄、有基础病和服务不足地区居民风险更大，家庭照护承担大量工作。官方医院死亡通报与社会全部死亡不是同一范围，世界卫生组织要求更详细数据。病例减少也会受到检测缩减影响，不能把通报下降直接当成传播完全结束。',
      'Rapid relaxation brought surging infections and care demand. The need to end unsustainable controls differs from whether timing and preparation were adequate. Alternatives were not limited to sudden exit or endless lockdown.\n\nOlder people and poorly served regions faced greater risk. Hospital deaths and population mortality differ, while reduced testing changes case counts.', ['who-china-2023', 'covid-excess-2023']),
    d('超额死亡研究与测量限制', 'Excess-mortality research and measurement limits',
      '超额死亡比较实际与假设正常死亡，包括直接感染和医疗延误等多种路径，不等于每例都被确诊为新冠死亡。2023年JAMA研究利用三所大学讣告与搜索数据外推全国变化，提示退出后死亡显著增加，同时受代表性、搜索行为和基准假设限制。\n\n模型估计不是逐人登记，区间不能省去，其他方法也可能得到不同结果。官方有限范围通报又不能被当成所有死亡上限。本站不把二者放进同一柱状图装作同口径，而说明各自测量什么、遗漏什么，让大规模损失与估计不确定性同时可见。',
      'Excess mortality includes multiple pathways beyond confirmed infection. A 2023 JAMA study extrapolated university obituaries and search data, finding a substantial increase with important representativeness and baseline limits.\n\nModels are not registers, and restricted official reports are not population upper bounds. Different measures are explained rather than graphed as comparable counts.', ['covid-excess-2023', 'who-china-2023']),
    d('疫情后遗产与责任记录', 'Post-pandemic legacies and accountability',
      '复工和出行恢复不使丧亲、长期健康、失学和债务问题立即消失。医护劳动、家庭互助与志愿行动应被记住，失误、隐瞒和不必要强制也需进入记录。个人感染不是道德失败，家庭不应因风险选择而互相污名化。\n\n持续公共卫生准备需要疫苗、监测、基层医疗、可信信息和社会保障。历史教训不是选择最严或最松的固定口号，而是依据证据调整、保护弱者与保留纠错。本书以资料截止日前可核查记录为准，尚缺的完整死亡、长期影响与内部决策资料公开列为后续研究问题。',
      'Reopening did not erase bereavement, lasting illness, disrupted learning or debt. Recognition of care and mutual aid belongs beside investigation of concealment and unnecessary coercion.\n\nPreparation requires monitoring, credible information and social protection. Missing mortality and decision records remain explicit research needs rather than invented certainty.', ['who-timeline', 'who-china-2023', 'covid-excess-2023']),
  ],
  'climate-transition': [
    d('污染治理与气候政策的区别', 'Pollution control and climate policy',
      '空气、水和土壤污染直接影响健康，温室气体则通过全球气候机制产生长期风险，两者有关却不同。减少煤炭燃烧可能同时降低颗粒物和碳排放，某些末端治污技术却主要处理局部污染。不能用空气变清洁直接证明总碳排放下降。\n\n环境治理经历从工业扩张、地方保护到更集中监管的变化，居民投诉、媒体、科研和政策共同推动。执法改善可产生实际收益，突击停产和不透明检查又可能损害企业与工人。完整评价需要看持续排放、健康和执行公平，而不只看一次专项行动。',
      'Local pollution and greenhouse gases differ, despite shared sources. Cleaner air does not itself establish lower total carbon emissions.\n\nResidents, research and regulation shaped change. Enforcement benefits coexist with risks from abrupt controls; durable emissions and fair implementation matter.', ['climate-ndc', 'nbs-2025']),
    d('2030与2060目标的含义', 'The 2030 and 2060 targets',
      '中国提出2030年前碳达峰、2060年前碳中和，并通过国家自主贡献文件说明目标和措施。达峰关注排放由增转降的时间，中和涉及排放与吸收平衡，两者不是同一指标，也不意味着到达目标前可以无约束增加排放。\n\n目标文本是国际承诺和政策方向，不是已经实现的数据。比较排放总量、人均、单位GDP及消费责任会得到不同视角，需要标明范围。历史工业化和当代生产责任同时存在，不能用其中一个维度否定其他维度，也不能把发展权当作免除所有减排义务。',
      'Peaking before 2030 and neutrality before 2060 are distinct commitments, not completed results. Total, per-capita, intensity and consumption-based emissions use different perspectives.\n\nHistorical and present responsibilities coexist. Development needs do not remove every mitigation duty.', ['climate-ndc']),
    d('新能源扩张与电网约束', 'Renewables and grid constraints',
      '风电、光伏、电动车和储能发展改变制造业与能源结构，规模扩大推动成本下降和技术进步。装机容量不等于实际发电，发电量又不等于在每个时段可稳定送达用户。电网、调峰、储能和跨区域输电决定可再生能源利用。\n\n煤电承担供电与调节角色，使新增清洁能源与煤炭使用可能同时发生，不能仅凭一个项目判断全国转型方向。能源安全、价格和排放之间需要协调，地方投资竞争也可能造成重复建设。数据图应区分容量、产量和能源消费，不把不同单位放在同一比较轴上。',
      'Wind, solar, vehicles and storage expanded capabilities, but installed capacity differs from delivered electricity. Grids and flexibility determine utilization.\n\nCoal and clean additions can coexist. Security, price and emissions require coordination; capacity and consumption should not share a misleading axis.', ['nbs-2025', 'climate-ndc']),
    d('煤炭地区与公正转型', 'Coal regions and a fair transition',
      '减煤和产业调整影响矿工、地方财政和依赖单一产业的城市，新增绿色岗位未必在同一地点或适合原技能。不能把全国新能源就业增加当作每名下岗工人已经获得补偿。培训、养老金、迁移和公共服务决定转型能否公平。\n\n新能源生产也需要矿产、土地、水和设备处理，绿色标签不使供应链自动没有环境问题。居民参与、劳动安全与回收制度应伴随扩张。2026年世界银行更新讨论绿色技能与社会保障，属于对转型条件的分析，不能写成所有技能缺口已经补齐。',
      'Coal adjustment affects workers and local budgets, while green jobs may differ in location and skills. Aggregate job gains do not compensate each displaced worker.\n\nClean technology also requires minerals and land. Labor, recycling and consultation remain necessary; the 2026 World Bank analysis identifies skill needs rather than completed solutions.', ['wb-2026', 'climate-ndc', 'nbs-2025']),
    d('国际贸易与绿色产业竞争', 'Trade and competition in green industry',
      '中国新能源制造降低部分全球转型成本，也引发补贴、产能与市场竞争争议。贸易伙伴对电动车、光伏等采取措施，国家安全、产业保护和气候目标可能互相冲突。应具体说明法律和产品，不把任何绿色产品关税都视作同一理由。\n\n低价格可能来自规模、技术、投入和政策，多种因素需要实证分辨。国内外消费者、工人和财政承担不同成本，全球减排又需要合作。历史分析不应只问哪国赢得产业，还应问技术是否减少排放、劳动与环境是否受保护，以及竞争规则是否可持续。',
      'Chinese manufacturing reduced some transition costs while provoking subsidy and capacity disputes. Trade, industry and climate priorities can conflict.\n\nPrices reflect multiple causes. Consumer, worker and fiscal effects coexist with global mitigation needs, requiring more than a national winner–loser frame.', ['trade-review', 'climate-ndc', 'wb-2026']),
    d('核查目标与实测的时间差', 'The time gap between pledges and observations',
      '年度能源数据、企业报告和国际清单可能使用不同边界与修订方式，不能选择最有利数字拼成连续成就曲线。碳市场、地方计划和产业投资需要后续排放核查，交易量也不直接等于净减排。政策有效性依赖基准、额外性与执行。\n\n2026年仍未结束，本书不声称掌握全年最终排放。未来更新将保留数据发布日、测量单位和预测标签，用实际趋势检验承诺。图表的作用是帮助理解制度和数据，不是用未来目标填补尚不存在的观测值。',
      'Energy data and emissions inventories use differing boundaries and revisions. Trading volume does not equal additional mitigation; baselines and enforcement matter.\n\nNo final 2026 emissions are claimed. Future updates will preserve release dates, units and forecast labels rather than filling missing observations with targets.', ['climate-ndc', 'nbs-2025']),
  ],
  'demographic-turn': [
    d('2025年数据的准确范围', 'The precise scope of the 2025 data',
      '国家统计局2025年统计公报报告出生792万人、死亡1131万人，年末人口140489万人，比上年减少339万人。公报于2026年发布，数字描述2025年而非2026年。人口范围为大陆31个省区市及现役军人，不包括港澳台居民及外籍人员等，不能用作同口径的全部中国疆域人口。\n\n出生减死亡得到自然减少，年末人口变化还需注意统计与调整口径。将人口总量、自然增长率和年龄结构同时观察，才能理解趋势。单一年份下降不是每个地区都相同，也不能据此推定某项短期政策已经完全有效或无效。',
      'The 2025 communiqué reported 7.92 million births, 11.31 million deaths and 1,404.89 million year-end population, down 3.39 million. Released in 2026, it describes 2025 mainland coverage including military personnel, not all territorial populations.\n\nTotals, natural change and age structure differ. One year does not establish uniform regional trends or a short-term policy’s causal effect.', ['nbs-2025']),
    d('低生育的多重原因', 'Multiple causes of low fertility',
      '生育选择受育龄人口、婚姻、教育、住房、工作和照护共同影响，过去政策又改变家庭结构与预期。不能把低生育只归为年轻人观念，也不能认为单独取消数量限制就能回到高生育。女性机会扩展是社会进步，家庭支持不足则使生育与职业形成不必要冲突。\n\n调查意愿与实际出生不同，结婚人数也不能直接换算下一年出生。经济不确定、就业歧视和祖辈照护资源使家庭差异显著。政策研究需要比较可负担托育、父母共同休假和稳定保障，而不是将女性身体当成达成人口目标的工具。',
      'Cohorts, marriage, education, housing, employment and care interact with earlier policy. Low fertility cannot be reduced to attitudes or restored merely by removing limits.\n\nIntentions and births differ. Childcare, shared leave and secure work address constraints without treating women’s bodies as targets.', ['birth-policy', 'birth-policy-study', 'unfpa-programme']),
    d('老龄化不等于老年人是负担', 'Aging without treating older people as a burden',
      '寿命延长是重要成就，老龄化同时改变养老、医疗和劳动安排。健康老人仍可工作、照顾家庭和参与公共生活，不能按年龄把所有人视作依赖者。高龄、失能和低收入群体则需要不同支持，平均寿命不能表示每个人拥有同样健康年限。\n\n养老金、长期护理和社区服务的城乡差异影响家庭责任，女性常承担更多无偿照护。家庭养老与社会服务不是非此即彼，适当公共支持可以减少亲属耗竭。讨论财政可持续时也应承认老人一生贡献和权利，不把代际关系写成争夺资源的简单战争。',
      'Longer lives are an achievement, while care and labor needs change. Older people vary in health and contribution; age alone does not define dependence.\n\nUnequal pensions and services place care burdens, often on women. Public support can complement families, with dignity and contribution recognized alongside fiscal sustainability.', ['unfpa-programme', 'nbs-2025', 'poverty-report']),
    d('劳动人口与生产率', 'Workforce size and productivity',
      '劳动年龄人口变化会影响供给，却不机械决定经济增长。教育、技术、健康、劳动参与和资源配置可以改变每名劳动者产出，自动化也可能补充某些岗位而替代另一些岗位。不能因人口减少就预判必然崩溃，也不能以技术进步保证所有压力自动消失。\n\n退休、职业培训与跨地区流动政策需要考虑工种和健康，办公室与重体力劳动者并不具有相同延长工作的能力。青年就业不足和企业招工困难也可能并存，表明技能与地区匹配重要。人口史应连接制度和劳动，而不是只用一条总人口曲线解释全部经济。',
      'Workforce decline affects supply without mechanically determining growth. Skills, health, participation and technology alter productivity, with uneven automation effects.\n\nRetirement and retraining must account for occupation and health. Youth unemployment can coexist with shortages through mismatch; a population curve alone cannot explain the economy.', ['nbs-2025', 'wb-2026', 'unfpa-programme']),
    d('地区收缩与人口流动', 'Regional shrinkage and mobility',
      '全国人口转折伴随城市和地区重新分布，一些都市圈吸引人口，部分县域与老工业地区持续流出。学校、医院和住房供给需要适应，但不能仅按规模效率关闭所有小地方服务。留守老人、儿童和交通不便家庭可能因此承担更高成本。\n\n户籍、财政与常住人口之间的衔接决定流动者能否取得权利，人口迁入也需要住房和基础设施。空置住房总量并不表示每位城市居民买得起房，地域和品质不同。比较人口与房地产应使用对应地区，避免全国总量掩盖城市之间完全不同的情况。',
      'National decline coexists with concentration in some metropolitan areas and outflow elsewhere. Service consolidation can raise costs for residents with limited mobility.\n\nResidence-based rights and finance matter for migrants. Vacant housing does not guarantee affordability where demand exists; geography and quality require matching.', ['nbs-2025', 'wb-2026', 'hukou-1958']),
    d('尊重选择的长期社会政策', 'Long-term policy that respects choice',
      '人口政策需要从单一数量管理转向人的健康、教育、照护与自主选择。支持希望生育的家庭与尊重不生育者可以同时进行，不能把未婚或少生者当作不负责任。移民、延长健康工作与提高生产率也属于讨论，但各有制度和权利条件。\n\n长期变化不可能由一次补贴立刻逆转，评估应预先明确目标和时间，保留未达预期的结果。2026年最终人口数据尚未公布，本书以2025年公报为最新完整年度基础。未来更新将记录修订和新证据，避免把政策愿望提前写成社会事实。',
      'Policy can support desired births while respecting those who do not have children. Health, education and care matter beyond targets, with other options subject to rights and institutions.\n\nLong-term trends cannot be instantly reversed. The latest complete annual basis here is 2025; final 2026 population is not invented.', ['unfpa-programme', 'nbs-2025', 'wb-2026']),
  ],
  'china-2026': [
    d('当代史的开放结尾', 'An open ending for contemporary history',
      '1840年至2026年的长时段不能在最后一年写出已经确定的结局，当前经济、社会和国际关系仍在变化。本书资料截止日为2026年10月10日，修订于10月11日，之后事件不在本次编年事实范围。未来发表的数据也可能重新解释过去，历史叙述需要版本记录。\n\n2026年的已公布季度资料、2025年完整年度数据和对2027年的预测具有不同地位。页面显示的日期不是信息自动实时更新的保证，读者应能核查每项来源。本章连接长期机制与当前约束，避免将当下感受扩写成对未来必然性的判断。',
      'The account ends openly, with evidence through 10 October 2026 and revision on 11 October. Later events and retrospective revisions require new versions.\n\nQuarterly observations, complete 2025 data and future forecasts differ. A page date does not imply automatic real-time updating; sources remain checkable.', ['wb-2026', 'nbs-2025']),
    d('房地产调整与家庭资产', 'Property adjustment and household assets',
      '房地产调整牵动开发商、购房家庭、建筑就业和地方财政，住房交付、债务与价格变化影响信心。拥有多套资产、刚购房和租房家庭的处境不同，不能用平均房价下跌说明每个人受损或受益。地方土地收入下降又可能传到公共服务和偿债。\n\n政策支持交付和稳定市场时，需要区分保护居民、救助企业与转移损失。不能把每项支持都视为相同的刺激，也不能仅因项目完成就认定原有投资合理。长期问题涉及住房需求、人口和财政结构，历史上形成的增长模式需要逐步重组。',
      'Property adjustment affects developers, buyers, construction and local finance unevenly. Average prices do not identify every household’s gain or loss.\n\nCompletion support, firm rescue and loss redistribution are distinct. Long-term change involves housing demand, demography and fiscal structure rather than one stabilization measure.', ['wb-2026', 'stimulus-study', 'housing-1998']),
    d('消费、储蓄与社会保障', 'Consumption, saving and social protection',
      '内需不足不能只解释为居民不愿消费，收入预期、住房负担、医疗、养老和教育支出都会影响预防性储蓄。扩大保障可能提高消费信心，收入分配和就业同样重要。消费占比变化还受投资、出口和价格影响，不能只看某个商场人流作宏观结论。\n\n非正规就业与流动人口若无法同等获得服务，会在城市贡献与家庭风险之间形成缺口。2026年世界银行更新强调更强社会安全网及按居住提供服务的条件，这是政策分析而非所有问题已经解决。公共支出方向和可持续财政需要一起考虑。',
      'Cautious consumption reflects income, housing and service risks, not merely unwillingness. Distribution and employment matter alongside protection.\n\nInformal workers and migrants face gaps. The 2026 World Bank update discusses stronger residence-based services as a condition, not an accomplished outcome.', ['wb-2026', 'poverty-report', 'nbs-2025']),
    d('创新投资与经济结构', 'Innovation investment and economic structure',
      '高技术制造和人工智能投资带来新能力，也需区分投入、产品应用与实际生产率。专利、论文或模型参数不直接代表社会收益，重复投资和评估失真可能消耗资源。科研自主与国际知识交流具有张力，却也可能相互支持，不能预设只有一种发展路径。\n\n企业、大学、研究者和用户分别承担风险与贡献，产业政策需要真实反馈。2026年讨论的增长支撑不能被写成未来技术一定成功，安全和信任又是应用能否持续的条件。历史叙述应保留失败和被忽略的劳动，避免只收集获奖与发布会。',
      'High-tech and AI investment create capacity, but inputs and patents do not establish productivity or social value. Evaluation and duplication risks remain.\n\nFirms, researchers and users contribute differently. Forecast support from innovation does not guarantee future success; safety, trust and records of failure matter.', ['wb-2026', 'ai-rules', 'nbs-2025']),
    d('全球环境与政策预测', 'Global conditions and policy forecasts',
      '世界银行2026年7月更新预计当年增长4.4%、2027年4.3%，这些是该时点预测，不是已经实现的年度增长率。房地产、消费、能源和外部需求会使结果偏离预测，不能选择一次预测当作最终历史结论。不同机构模型与发布日期也需保留。\n\n贸易、技术和气候政策跨国相互作用，国内发展不能完全脱离国际环境解释。国家竞争叙述容易忽略跨境家庭、工人和消费者共同承受的成本。研究应比较合作与冲突的具体结果，以证据检验政策而非只沿某一政府立场排列事件。',
      'The World Bank’s July 2026 forecasts of 4.4% for 2026 and 4.3% for 2027 are dated expectations, not realized annual growth. Subsequent conditions may differ.\n\nTrade, technology and climate interact internationally. Cross-border household and worker costs complement national narratives, with policies tested against evidence.', ['wb-2026', 'trade-review', 'climate-ndc']),
    d('公开范围与后续史料工作', 'Public scope and future evidence work',
      '本书以明确编年总目覆盖各阶段及政治、战争、经济、社会、文化、环境和国际关系，并提供人物行动与专题长章。它不是宣称穷尽每个县、每个家庭与每一天，而是让已经纳入和仍待增补的范围可核查。扩充地方和口述史需要新的原始材料，不能靠重复通史段落替代。\n\n后续工作包括更细地方史、家庭经验、原始档案校勘及新发布统计，重大争议保留不同证据的可追踪出处。新增内容同样遵循中英对应、来源说明和不确定性标记。开放结尾让读者看到研究过程，也避免把2026年临时判断封成永远不变的终章。',
      'The explicit chronology covers phases and major themes, with biographies, actions and studies. It does not claim every county or day; included and future scope remain auditable.\n\nLocal, oral and archival work requires new evidence rather than repeated general prose. Future bilingual additions retain sources, limitations and versioned statistics.', ['nbs-2025', 'wb-2026', 'political-campaign-databases']),
  ],
};
